      AND (${Fragment.encode(MariaTypes.bool.opt, lowStockOnly)} IS NULL OR (i.quantity_on_hand - i.quantity_reserved) <= i.reorder_point)
    """.query(InventoryCheckSqlRow.rowCodec.all()).run(using c)
  }
